  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Ruhe statt Arbeit','استراحت به‌جای کار','Mia plant eine kurze Krankmeldung und erklärt die Hinweise zu Wasser und Schlaf.','میا برای مرخصی بیماری کوتاه برنامه می‌ریزد و توصیه‌های مربوط به آب و خواب را توضیح می‌دهد.','story','mia-sara-b1-health-routine',6,54,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"plan-recovery"}'); SET v_l_2=LAST_INSERT_ID();
