  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,2,'learner','Nein, ich melde mich für zwei Tage krank.','نه، برای دو روز مرخصی بیماری می‌گیرم.',54,NULL,NULL,'nein ich melde mich für zwei tage krank',NULL,'[{"surface":"Nein","lemma":"nein","translation":"نه","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"melde","lemma":"sich krankmelden","translation":"مرخصی بیماری گرفتن","partOfSpeech":"verb"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"für","lemma":"für","translation":"برای","partOfSpeech":"preposition"},{"surface":"zwei","lemma":"zwei","translation":"دو","partOfSpeech":"number"},{"surface":"Tage","lemma":"Tag","translation":"روز","partOfSpeech":"noun"},{"surface":"krank","lemma":"sich krankmelden","translation":"مرخصی بیماری گرفتن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_8=LAST_INSERT_ID();
