  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Ein ruhiger Abend','یک شب آرام','Sara hilft Mia, den Abend ruhig zu organisieren und belastende Aufgaben zu vermeiden.','سارا به میا کمک می‌کند شب آرامی برنامه‌ریزی کند و از کارهای خسته‌کننده دور بماند.','story','mia-sara-b1-health-routine',7,54,180,3,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"support-evening-rest"}'); SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,1,'character','Dann solltest du dein Handy heute Abend ausschalten.','پس بهتر است امشب گوشی‌ات را خاموش کنی.',54,NULL,NULL,NULL,NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"solltest","lemma":"sollen","translation":"باید / قرار است","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"dein","lemma":"dein","translation":"مال تو / تو","partOfSpeech":"determiner"},{"surface":"Handy","lemma":"Handy","translation":"گوشی","partOfSpeech":"noun"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"Abend","lemma":"Abend","translation":"عصر / شب","partOfSpeech":"noun"},{"surface":"ausschalten","lemma":"ausschalten","translation":"خاموش کردن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_13=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,2,'learner','Ja, ich will heute Abend wirklich früh schlafen.','بله، می‌خواهم امشب واقعاً زود بخوابم.',54,NULL,NULL,'ja ich will heute abend wirklich früh schlafen',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"will","lemma":"wollen","translation":"خواستن","partOfSpeech":"verb"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"Abend","lemma":"Abend","translation":"عصر / شب","partOfSpeech":"noun"},{"surface":"wirklich","lemma":"wirklich","translation":"واقعا","partOfSpeech":"adverb"},{"surface":"früh","lemma":"früh","translation":"زودتر","partOfSpeech":"adverb"},{"surface":"schlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_14=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,3,'character','Soll ich für dich einkaufen?','برای تو خرید کنم؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Soll","lemma":"sollen","translation":"باید / قرار است","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"für","lemma":"für","translation":"برای","partOfSpeech":"preposition"},{"surface":"dich","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"einkaufen","lemma":"einkaufen","translation":"خرید کردن","partOfSpeech":"verb","suffix":"?"}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_15=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,4,'learner','Gern, dann muss ich nicht selbst rausgehen.','با میل، آن‌وقت لازم نیست خودم بیرون بروم.',54,NULL,NULL,'gern dann muss ich nicht selbst rausgehen',NULL,'[{"surface":"Gern","lemma":"gern","translation":"با علاقه / با میل","partOfSpeech":"adverb","suffix":","},{"surface":"dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"muss","lemma":"müssen","translation":"مجبور بودن / باید","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"adverb"},{"surface":"selbst","lemma":"selbst","translation":"خود / خودم","partOfSpeech":"pronoun"},{"surface":"rausgehen","lemma":"rausgehen","translation":"بیرون رفتن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_16=LAST_INSERT_ID();
