  INSERT INTO activities(lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES(v_l_3,'reading_comprehension',8,NULL,NULL,'مکالمه را بخوان و پاسخ بده',NULL,54,'{"source":"lesson_story","question":"سارا چه کمکی پیشنهاد می‌دهد؟","choices":["خرید و پختن سوپ","رزرو سفر","انجام کار اداری"],"correctIndex":0}','{"cefr":"B1","series":102}');
  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Dem ärztlichen Rat folgen','پیروی از توصیهٔ دکتر','Mia entscheidet sich, den ärztlichen Rat ernst zu nehmen, und nennt ihren nächsten Schritt.','میا تصمیم می‌گیرد توصیهٔ دکتر را جدی بگیرد و گام بعدی‌اش را بیان می‌کند.','story','mia-sara-b1-health-routine',8,54,180,4,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"commit-to-recovery"}'); SET v_l_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,1,'character','Willst du dem Rat des Arztes folgen?','می‌خواهی از توصیهٔ دکتر پیروی کنی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Willst","lemma":"wollen","translation":"خواستن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"dem","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Rat","lemma":"Rat","translation":"توصیه / راهنمایی","partOfSpeech":"noun"},{"surface":"des","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Arztes","lemma":"Arzt","translation":"دکتر","partOfSpeech":"noun"},{"surface":"folgen","lemma":"folgen","translation":"پیروی کردن","partOfSpeech":"verb","suffix":"?"}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,2,'learner','Ja, ich nehme seine Empfehlung ernst.','بله، توصیه‌اش را جدی می‌گیرم.',54,NULL,NULL,'ja ich nehme seine empfehlung ernst',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"nehme","lemma":"nehmen","translation":"گرفتن / مصرف کردن","partOfSpeech":"verb"},{"surface":"seine","lemma":"sein","translation":"مال او / او","partOfSpeech":"determiner"},{"surface":"Empfehlung","lemma":"Empfehlung","translation":"توصیه","partOfSpeech":"noun"},{"surface":"ernst","lemma":"ernst","translation":"جدی","partOfSpeech":"adjective","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_20=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,3,'character','Was machst du, wenn es nicht besser wird?','اگر بهتر نشوی چه کار می‌کنی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Was","lemma":"was","translation":"چی / چه","partOfSpeech":"pronoun"},{"surface":"machst","lemma":"machen","translation":"انجام دادن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun","suffix":","},{"surface":"wenn","lemma":"wenn","translation":"اگر / وقتی","partOfSpeech":"conjunction"},{"surface":"es","lemma":"es","translation":"آن / این / ضمیر خنثی","partOfSpeech":"pronoun"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"adverb"},{"surface":"besser","lemma":"gut","translation":"خوب","partOfSpeech":"adjective"},{"surface":"wird","lemma":"werden","translation":"شدن / خواهد","partOfSpeech":"verb","suffix":"?"}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_21=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,4,'learner','Dann gehe ich noch einmal zum Arzt.','آن‌وقت یک بار دیگر پیش دکتر می‌روم.',54,NULL,NULL,'dann gehe ich noch einmal zum arzt',NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"gehe","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"einmal","lemma":"einmal","translation":"یک بار","partOfSpeech":"adverb"},{"surface":"zum","lemma":"zu","translation":"به / به سمت","partOfSpeech":"preposition"},{"surface":"Arzt","lemma":"Arzt","translation":"دکتر","partOfSpeech":"noun","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_22=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,5,'character','Das klingt nach einem guten Plan.','این برنامهٔ خوبی به نظر می‌رسد.',54,NULL,NULL,NULL,NULL,'[{"surface":"Das","lemma":"das","translation":"این / آن","partOfSpeech":"pronoun"},{"surface":"klingt","lemma":"klingen","translation":"به نظر رسیدن","partOfSpeech":"verb"},{"surface":"nach","lemma":"nach","translation":"پس از / به","partOfSpeech":"preposition"},{"surface":"einem","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"guten","lemma":"gut","translation":"خوب","partOfSpeech":"adjective"},{"surface":"Plan","lemma":"Plan","translation":"برنامه","partOfSpeech":"noun","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_23=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,6,'learner','Ich hoffe, dass ich bald wieder gesund bin.','امیدوارم به‌زودی دوباره سالم شوم.',54,NULL,NULL,'ich hoffe dass ich bald wieder gesund bin',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"hoffe","lemma":"hoffen","translation":"امیدوار بودن","partOfSpeech":"verb","suffix":","},{"surface":"dass","lemma":"dass","translation":"که","partOfSpeech":"conjunction"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"bald","lemma":"bald","translation":"به‌زودی","partOfSpeech":"adverb"},{"surface":"wieder","lemma":"wieder","translation":"دوباره","partOfSpeech":"adverb"},{"surface":"gesund","lemma":"gesund","translation":"سالم","partOfSpeech":"adjective"},{"surface":"bin","lemma":"sein","translation":"بودن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_24=LAST_INSERT_ID();
